def give_existing_profiles_a_referral_code(apps, schema_editor):
    import random
    Profile = apps.get_model("core", "Profile")
    alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
    used = set(Profile.objects.exclude(referral_code=None).values_list("referral_code", flat=True))
    for profile in Profile.objects.filter(referral_code=None):
        while True:
            code = "".join(random.choice(alphabet) for _ in range(7))
            if code not in used:
                used.add(code)
                break
        Profile.objects.filter(pk=profile.pk).update(referral_code=code)


